static uint8_t *bgp_notify_encapsulate_hard_reset(uint8_t code, uint8_t subcode, /* <=== bgp_notify_encapsulate_hard_reset */ 
						  uint8_t *data, size_t datalen)
{
	uint8_t *message = XCALLOC(MTYPE_BGP_NOTIFICATION, datalen + 2);

	/* ErrCode */
	message[0] = code;
	/* Subcode */
	message[1] = subcode;
	/* Data */
	if (datalen)
		memcpy(message + 2, data, datalen);

	return message;
}

